package com.example.agroconnect.controller;
import com.example.agroconnect.model.*; import com.example.agroconnect.repository.*; import jakarta.servlet.http.HttpSession; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/loan-history") @CrossOrigin(origins="http://localhost:5173",allowCredentials="true") public class LoanHistoryController {private final LoanRepository loans;private final LoanStatusHistoryRepository history;public LoanHistoryController(LoanRepository l,LoanStatusHistoryRepository h){loans=l;history=h;}
 private boolean allowed(Loan l,HttpSession s){Object uid=s.getAttribute("userId");return uid!=null&&("ADMIN".equals(s.getAttribute("role"))||(l.getFarmer()!=null&&l.getFarmer().getUser()!=null&&l.getFarmer().getUser().getId().toString().equals(uid.toString())));}
 @GetMapping("/{loanId}") public ResponseEntity<?> list(@PathVariable Long loanId,HttpSession s){Loan l=loans.findById(loanId).orElse(null);if(l==null)return ResponseEntity.notFound().build();if(s.getAttribute("userId")==null)return ResponseEntity.status(401).body("Please login first");if(!allowed(l,s))return ResponseEntity.status(403).body("Not allowed");return ResponseEntity.ok(history.findByLoanLoanIdOrderByChangedAtDesc(loanId));}
 @PostMapping("/{loanId}") public ResponseEntity<?> add(@PathVariable Long loanId,@RequestBody Map<String,String> body,HttpSession s){Loan l=loans.findById(loanId).orElse(null);if(l==null)return ResponseEntity.notFound().build();if(s.getAttribute("userId")==null)return ResponseEntity.status(401).body("Please login first");if(!"ADMIN".equals(s.getAttribute("role")))return ResponseEntity.status(403).body("Only admin can add manual history entries");LoanStatusHistory h=new LoanStatusHistory();h.setLoan(l);h.setNewStatus(body.getOrDefault("status",l.getLoanStatus()));h.setPreviousStatus(body.get("previousStatus"));h.setChangedBy(String.valueOf(s.getAttribute("userId")));h.setNote(body.getOrDefault("note",""));return ResponseEntity.ok(history.save(h));}
}
